import requests
terms=['lung transplantation pretransplant impedance reflux primary graft dysfunction','lung transplant pre-transplant esophageal impedance acute rejection','lung transplantation reflux impedance allograft injury pretransplant']
for term in terms:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
 d=requests.get(u,params={'db':'pubmed','term':term,'retmode':'json','retmax':20},timeout=20).json()
 ids=d['esearchresult']['idlist']
 print('\nQUERY:',term,'\nPMIDS:',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
